      next();
    });
  });

  it('GET querystring object .get(uri, obj, fn)', (next) => {
    request.get('/querystring', { search: 'Manny' }, (error, res) => {
      assert.deepEqual(res.body, { search: 'Manny' });
      next();
    });
  });

