const assert = require('assert');
const getSetup = require('../support/setup');
const request = require('../support/client');

describe('request and response size limits', () => {
  let base;

  before(async () => {
    const setup = await getSetup();
    base = setup.uri;
  });

  it('exposes a strict boolean before and after a size error', (done) => {
    const request_ = request.post(`${base}/echo`).maxRequestSize(2);

    assert.strictEqual(request_.hasSizeError(), false);
    request_.send('é').end((error) => {
      assert.ifError(error);
      assert.strictEqual(request_.hasSizeError(), false);
      done();
    });
  });

  it('counts .send() bodies in bytes and allows an exact limit', (done) => {
    const request_ = request.post(`${base}/echo`).maxRequestSize(2);

    request_.send('é').end((error) => {
      assert.ifError(error);
      assert.strictEqual(request_.hasSizeError(), false);
      done();
    });
  });

  it('returns ETOOLARGE for an oversized .send() body', (done) => {
    const request_ = request.post(`${base}/echo`).maxRequestSize(2);

    request_.send('éx').end((error) => {
      assert(error);
      assert.strictEqual(error.code, 'ETOOLARGE');
      assert.strictEqual(request_.hasSizeError(), true);
      done();
    });
  });

  it('counts .write() bodies in bytes', (done) => {
    const request_ = request
      .post(`${base}/echo`)
      .type('text/plain')
      .maxRequestSize(3);

    assert.strictEqual(request_.write('é'), true);
    assert.strictEqual(request_.write('x'), true);
    request_.end((error) => {
      assert.ifError(error);
      assert.strictEqual(request_.hasSizeError(), false);
      done();
    });
  });

  it('terminates an oversized .write() body', (done) => {
    const request_ = request
      .post(`${base}/echo`)
      .type('text/plain')
      .maxRequestSize(2);

    request_.write('é');
    assert.strictEqual(request_.write('x'), false);
    request_.end((error) => {
      assert(error);
      assert.strictEqual(error.code, 'ETOOLARGE');
      assert.strictEqual(request_.hasSizeError(), true);
      done();
    });
  });

  it('does not retry oversized responses or call back twice', (done) => {
    const request_ = request
      .get(`${base}/json`)
      .buffer(true)
      .maxResponseSize(1)
      .retry(2);
    let callbackCount = 0;

    request_.end((error) => {
      callbackCount++;
      assert(error);
      assert.strictEqual(error.code, 'ETOOLARGE');
      assert.strictEqual(error.retries, 0);
      assert.strictEqual(request_.hasSizeError(), true);
      setImmediate(() => {
        assert.strictEqual(callbackCount, 1);
        done();
      });
    });
  });

  it('enforces multipart Content-Length and emits upload progress', (done) => {
    const request_ = request
      .post(`${base}/echo`)
      .maxRequestSize(10000)
      .field('name', 'tobi');
    const progress = [];

    request_.on('progress', (event) => {
      if (event.direction === 'upload') progress.push(event);
    });
    request_.end((error) => {
      try {
        assert.ifError(error);
        assert(progress.length > 0);
        const lastProgress = progress[progress.length - 1];
        assert.strictEqual(lastProgress.loaded, lastProgress.total);
        done();
      } catch (err) {
        done(err);
      }
    });
  });

  it('returns ETOOLARGE before an oversized multipart upload starts', (done) => {
    const request_ = request
      .post(`${base}/echo`)
      .maxRequestSize(1)
      .field('name', 'tobi');

    request_.end((error) => {
      assert(error);
      assert.strictEqual(error.code, 'ETOOLARGE');
      assert.strictEqual(request_.hasSizeError(), true);
      done();
    });
  });
});
